// Ad hoc malformed-TIFF probe: expects std::runtime_error, never crash/hang.
#include <tiffcraft/TiffImage.hpp>
#include <tiffcraft/TiffExporter.hpp>
#include <iostream>
#include <fstream>
#include <sstream>
#include <cstring>

int main(int argc, char** argv) {
  const char* path = argv[1];
  const char* mode = argv[2];
  try {
    if (std::strcmp(mode, "image") == 0) {
      auto image = TiffCraft::TiffImage::read(path);
      std::cout << "loaded IFDs: " << image.ifds().size() << std::endl;
    } else if (std::strcmp(mode, "exporter") == 0) {
      TiffCraft::load(path, [](const TiffCraft::TiffImage::Header& h,
                               const TiffCraft::TiffImage::IFD& ifd,
                               TiffCraft::TiffImage::ImageData data) {
        // exercise the rational divide path via getIntVec on XResolution if present
        try {
          auto v = TiffCraft::TiffExporter::getIntVec(ifd, TiffCraft::Tag::XResolution);
          std::cout << "XResolution[0]=" << v[0] << std::endl;
        } catch (const std::runtime_error& e) {
          std::cout << "exporter path threw: " << e.what() << std::endl;
          throw;
        }
      });
    }
    std::cout << "NO_EXCEPTION" << std::endl;
    return 1;
  } catch (const std::runtime_error& e) {
    std::cout << "runtime_error: " << e.what() << std::endl;
    return 0;
  } catch (...) {
    std::cout << "other exception" << std::endl;
    return 2;
  }
}

